#include <stdio.h>
#include <stdlib.h>
struct Node { int data; struct Node *next; };
struct Node *push(struct Node *h, int v) {
    struct Node *n = malloc(sizeof *n);
    n->data = v; n->next = h; return n;
}
int main(void) { struct Node *h = 0;
    for (int i = 1; i <= 3; i++) h = push(h, i);
    for (struct Node *p = h; p; p = p->next) printf("%d", p->data);
    return 0;
}

#include <stdio.h>
struct Node { int data; struct Node *next; };
int main(void) {
    struct Node c = {3, 0}, b = {2, &c}, a = {1, &b};
    struct Node *prev = 0, *cur = &a;
    while (cur) { struct Node *nxt = cur->next; cur->next = prev; prev = cur; cur = nxt; }
    for (struct Node *p = prev; p; p = p->next) printf("%d", p->data);
    return 0;
}

#include <stdio.h>
struct Node { int data; struct Node *next; };
int main(void) {
    struct Node c = {3, 0}, b = {2, &c}, a = {1, &b};
    c.next = &a;
    struct Node *s = &a, *f = &a;
    while (f && f->next) { s = s->next; f = f->next->next; if (s == f) break; }
    printf("%d\n", s == f);
    return 0;
}

#include <stdio.h>
struct Node { int data; struct Node *next; };
int main(void) {
    struct Node e = {2, 0}, d = {2, &e}, c = {1, &d}, b = {2, &c}, a = {3, &b};
    struct Node *head = &a, **pp = &head;
    while (*pp) {
        if ((*pp)->data == 2) { struct Node *dead = *pp; *pp = dead->next; }
        else pp = &(*pp)->next;
    }
    for (struct Node *p = head; p; p = p->next) printf("%d", p->data);
    return 0;
}

#include <stdio.h>
struct Node { int data; struct Node *next; };
int main(void) {
    struct Node e = {5, 0}, d = {4, &e}, c = {3, &d}, b = {2, &c}, a = {1, &b};
    struct Node *s = &a, *f = &a;
    while (f->next && f->next->next) { s = s->next; f = f->next->next; }
    printf("%d\n", s->data);
    return 0;
}
